package glitch

import data.glitch_lib

# Define insecure patterns for detection
insecure_protocols = {"http://", "ftp://", "smtp://"}
insecure_attributes = {
    "validate_certs", "ssl_enforcement_enabled", "force_https", "https_only", 
    "enable_https", "encryption_in_transit", "public_network_access_enabled",
    "allow_blob_public_access", "enable_legacy_protocols", "ssl_mode", 
    "verify_certificate", "protocol", "endpoint", "source", "url"
}

# Check if a value contains insecure protocol patterns
contains_insecure_protocol(value) {
    value.ir_type == "String"
    regex.match("(?i)http://|ftp://|smtp://", value.value)
    not regex.match("(?i)https://", value.value)
} else {
    value.ir_type == "Sum"
    traverse(value, "(?i)http://|ftp://|smtp://")
    not traverse(value, "(?i)https://")
}

# Check attribute values for insecure settings
check_insecure_attr_value(value) {
    value.ir_type == "String"
    regex.match("(?i)no|false|disabled|http|ftp|smtp", value.value)
} else {
    value.ir_type == "Boolean"
    value.value == false
} else {
    contains_insecure_protocol(value)
}

# Get parent UnitBlock path for result reporting
get_parent_path(node) = path {
    [ub | glitch_lib._gather_parent_unit_blocks[ub]; walk(ub, [_, n]); n == node][0].path
} else {
    input.ir_type == "UnitBlock"
    input.path
} else {
    ""
}

# Main detection rule for insecure attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all attributes in the parent
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]
    attr.name == insecure_attributes[_]

    # Check if the attribute value is insecure
    check_insecure_attr_value(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": sprintf("Insecure attribute '%s' may lead to cleartext transmission of sensitive information (CWE-319)", [attr.name])
    }
}

# Detection rule for variables containing insecure URLs
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check all variables in the parent
    vars := glitch_lib.all_variables(parent)
    var := vars[_]

    # Check if variable value contains insecure protocol
    contains_insecure_protocol(var.value)

    result := {
        "type": "sec_https",
        "element": var,
        "path": parent.path,
        "description": "Variable contains insecure protocol URL, may lead to cleartext transmission (CWE-319)"
    }
}

# Detection rule for atomic units with insecure source/url attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check for common resource types that handle URLs
    node.type =~ "(?i)(get_url|remote_file|source|url|endpoint)"

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    attr.name =~ "(?i)(source|url|endpoint)"

    # Check if the value contains insecure protocol
    contains_insecure_protocol(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": sprintf("Insecure %s attribute uses cleartext protocol (CWE-319)", [attr.name])
    }
}

